import React, { useState } from 'react';
import { post } from '../services/api';

export default function UploadProofForm({ onSubmitted }) {
  const [fileData, setFileData] = useState(null);
  const [tx, setTx] = useState('');
  const [loading, setLoading] = useState(false);

  function handleFile(e) {
    const f = e.target.files[0];
    if (!f) return;
    const reader = new FileReader();
    reader.onload = () => setFileData(reader.result);
    reader.readAsDataURL(f);
  }

  async function submit(e) {
    e.preventDefault();
    if (!fileData) return alert('Please select a screenshot or paste a link');
    setLoading(true);
    try {
      const body = { amount: 0, transactionId: tx || `REF-${Date.now()}`, screenshotUrl: fileData };
      await post('/payments/submit', body);
      setFileData(null);
      setTx('');
      if (onSubmitted) onSubmitted();
    } catch (err) {
      alert(err.message || 'Upload failed');
    } finally { setLoading(false); }
  }

  return (
    <form onSubmit={submit} className="card" style={{ padding: 12 }}>
      <div>
        <label>Transaction reference (optional)</label>
        <input className="input" value={tx} onChange={(e) => setTx(e.target.value)} placeholder="Txn id or reference" />
      </div>
      <div style={{ marginTop: 8 }}>
        <label>Upload screenshot</label>
        <input type="file" accept="image/*" onChange={handleFile} />
      </div>
      {fileData && <div style={{ marginTop: 8 }}><img src={fileData} alt="preview" style={{ maxWidth: 240 }} /></div>}
      <div style={{ marginTop: 12 }}>
        <button className="btn" type="submit" disabled={loading}>{loading ? 'Submitting...' : 'Submit proof'}</button>
      </div>
    </form>
  );
}
